#!/usr/bin/env tsx
/**
 * `generate-docs` — captures `os --help` + `os <group> --help` for
 * every generated tag and writes a single markdown page to
 * `docs/operations/cli.md`.
 *
 * The CLI itself is the source of truth — this script never invents
 * any docs content; it shells out to the built binary and stitches
 * the help output. Regenerated by `pnpm docs:cli` as part of
 * `pnpm docs:all`. CI `check:docs` covers staleness.
 */

import { execFileSync } from 'child_process'
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'fs'
import { dirname, join, resolve } from 'path'
import { fileURLToPath } from 'url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const REPO_ROOT = resolve(__dirname, '../../..')
const CLI_BIN = join(REPO_ROOT, 'packages/cli/dist/index.js')
const MANIFEST = join(REPO_ROOT, 'packages/cli/src/generated/manifest.json')
const OUT_PATH = join(REPO_ROOT, 'docs/operations/cli.md')

function run(args: string[]): string {
  return execFileSync('node', [CLI_BIN, ...args], {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  })
}

function fence(s: string, lang = 'text'): string {
  return '```' + lang + '\n' + s.trim() + '\n```\n'
}

function main(): void {
  if (!existsSync(CLI_BIN)) {
    throw new Error(`CLI binary not found: ${CLI_BIN} (run \`pnpm --filter @opensteward/cli build\` first)`)
  }
  if (!existsSync(MANIFEST)) {
    throw new Error(`Manifest not found: ${MANIFEST} (run \`pnpm cli:generate\` first)`)
  }
  const manifest = JSON.parse(readFileSync(MANIFEST, 'utf8')) as Array<{
    command: string
    operationId: string
    spec: 'admin' | 'public'
    tag: string
  }>
  const groups = [...new Set(manifest.map((m) => m.tag))].sort()
  const offlineGroups = ['backup', 'restore', 'doctor', 'rotate-secret']

  const out: string[] = []
  out.push('<!-- AUTOGENERATED by `pnpm docs:cli` — do not edit by hand. -->')
  out.push('')
  out.push('# `os` — OpenSteward CLI')
  out.push('')
  out.push('The `os` binary is the single operator + developer-facing CLI for an OpenSteward deployment. Every subcommand under a vertical or tag group (`os users`, `os platforms`, `os auth`, etc.) is **generated mechanically** from the OpenAPI specs at `docs/openapi/admin-api.openapi.json` (operator) and `docs/openapi/openapi.json` (public). Renaming a route in the spec renames the matching command on the next `pnpm cli:generate`.')
  out.push('')
  out.push('Install:')
  out.push('')
  out.push(fence('pnpm add -g @opensteward/cli\n# or, ad-hoc:\nnpx @opensteward/cli --help', 'bash'))
  out.push('')
  out.push('## Top-level usage')
  out.push('')
  out.push(fence(run(['--help'])))

  out.push('## Generated command groups')
  out.push('')
  out.push('Each of the groups below was generated from the OpenAPI specs and exposes one subcommand per operation in the matching tag. Help text, flags, required-ness, and response renderers are all derived from the spec — see [`docs/openapi/admin-api.openapi.json`](../openapi/admin-api.openapi.json) and [`docs/openapi/openapi.json`](../openapi/openapi.json) for the source.')
  out.push('')
  for (const g of groups.filter((g) => !offlineGroups.includes(g))) {
    out.push(`### \`os ${g}\``)
    out.push('')
    try {
      out.push(fence(run([g, '--help'])))
    } catch (err) {
      out.push(`> (failed to capture help for \`os ${g}\`: ${(err as Error).message})`)
      out.push('')
    }
  }

  out.push('## Offline tools')
  out.push('')
  out.push('These four subcommands wrap the filesystem-level scripts in `packages/shared/src/scripts/`. They have no OpenAPI representation because they operate directly on docker volumes / SQLite files — but they ship in the same `os` binary so a single operator runbook covers both online (admin-api) and offline operations.')
  out.push('')
  for (const g of offlineGroups) {
    out.push(`### \`os ${g}\``)
    out.push('')
    try {
      out.push(fence(run([g, '--help'])))
    } catch (err) {
      out.push(`> (failed to capture help for \`os ${g}\`: ${(err as Error).message})`)
      out.push('')
    }
  }

  mkdirSync(dirname(OUT_PATH), { recursive: true })
  writeFileSync(OUT_PATH, out.join('\n').trimEnd() + '\n', 'utf8')
  console.log(`[generate-docs] wrote ${OUT_PATH}`)
}

try {
  main()
} catch (err) {
  console.error('[generate-docs] FAILED:', (err as Error).message)
  process.exit(1)
}
